{
  "milestones": [
    {
      "id": "m1",
      "title": "Add week_start parameter to floor and ceil",
      "requests": [
        "R1"
      ],
      "requirement": "floor() and ceil() methods must accept an optional week_start argument (0-6) that determines which day is considered the start of the week for calculating the floor or ceiling.",
      "observable": "Arrow('2023-01-05').floor('week', week_start=0).day == 1; Arrow('2023-01-05').ceil('week', week_start=0).day == 8; Arrow('2023-01-05').floor('week', week_start=1).day == 2",
      "public_names": [
        "floor",
        "ceil"
      ],
      "requires": [],
      "why_requires": ""
    },
    {
      "id": "m2",
      "title": "Expose FORMAT_RFC3339_STRICT in public API",
      "requests": [
        "R2"
      ],
      "requirement": "The module-level constant FORMAT_RFC3339_STRICT must be available in the arrow package's public namespace, containing a format string with a 'T' separator between date and time.",
      "observable": "import arrow; assert 'T' in arrow.FORMAT_RFC3339_STRICT; arrow.Arrow.utcnow().format(arrow.FORMAT_RFC3339_STRICT) contains 'T'",
      "public_names": [
        "FORMAT_RFC3339_STRICT"
      ],
      "requires": [],
      "why_requires": ""
    }
  ],
  "expected_causes": [
    "Developers might confuse the week_start index (0-based Sunday vs 1-based Monday) with Python's weekday() return values or ISO standards, leading to off-by-one errors in the floor/ceil logic.",
    "Adding the new format constant requires ensuring it is correctly exported from arrow/__init__.py and defined in the formatter module without breaking existing imports or type hints."
  ],
  "verifier_plan": "For m1, tests will create Arrow objects at specific dates across different weeks and call floor/ceil with various week_start values (0-6), verifying the resulting datetime falls on the correct boundary. For m2, tests will import arrow, check that FORMAT_RFC3339_STRICT exists and contains 'T', and verify that formatting an Arrow object with this constant produces an ISO 8601 compliant string with 'T' separator."
}
